def transform(grid):
    rows = len(grid)
    cols = len(grid[0])

    background = grid[0][0]

    # Create rotated grid (180 degree rotation)
    rotated = [[background for _ in range(cols)] for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            rotated[rows - 1 - r][cols - 1 - c] = grid[r][c]

    # Overlay original with rotated
    result = [[background for _ in range(cols)] for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            for grid_source in [grid, rotated]:
                if grid_source[r][c] != background:
                    result[r][c] = grid_source[r][c]

    return result
